export interface BrowserOption {key:string;label:string;count?:number;value?:string|number;range?:NumericBucket;missing?:boolean;/** Shown after the label, e.g. the RAW paired with a JPEG. */badge?:string;/** One row for several values (JPG, JPEG and JPE as JPEG): choosing it chooses them all. */values?:(string|number)[];/** The selection bar's text for this row, when it differs from the label. */chip?:string;/** A tree row: its depth, and whether it has rows below it and shows them. */depth?:number;expandable?:boolean;expanded?:boolean;/** Some rows below it are chosen, not all: shown striped. */partial?:boolean;}
/** The values a row stands for, each as a row of its own, so a merged row is chosen and unchosen as a whole. */
export function memberOptions(row:BrowserOption):BrowserOption[]{return row.values?row.values.map(value=>({key:`value:${typeof value}:${value}`,value,label:row.chip??row.label,chip:row.chip??row.label})):[row];}
