const rangeKey=(range:NumericBucket)=>`range:${JSON.stringify(range)}`;
const membershipKey=(range:NumericBucket)=>range.min!==undefined&&range.min===range.max&&range.maxInclusive?`value:number:${range.min}`:rangeKey(range);
